contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs that choose between openMakeFor and openTakeFor and an amount.
    // The test checks that when calling either entrypoint, the contract does not increase its own Ether balance as a direct result of charging the position fee
    // (fees are settled via the controller->collateral and should not make c richer). We also assert the call never creates a negative position fee (represented: positionFee is UFixed18, non-negative).

    function run(bool openMake, address account, uint256 rawAmount) public payable {
        // normalize amount into a reasonable UFixed18 by multiplying; but we cannot construct UFixed18 directly.
        // We instead pick a small amount and call openMakeFor/openTakeFor; require non-zero account
        require(account != address(0), "bad account");

        // Record c balance before
        uint256 before = address(c).balance;

        bool reverted;
        // Call one of the mutating entrypoints. Must be top-level statements.
        if (openMake) {
            // call openMakeFor
            try c.openMakeFor(account, UFixed18.wrap(rawAmount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(rawAmount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after balance
        uint256 after = address(c).balance;

        // Rule: if the call did not revert, c's Ether balance must be <= before
        // (position fees settle out of account collateral, not into the product contract). Also, the call cannot increase c's balance.
        assert(reverted || after <= before);
    }

    // Fallbacks to allow receiving Ether if collateral interactions route funds to this test contract during controller/collateral callbacks
    receive() external payable {}
}

