contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entry that performs either openMakeFor or openTakeFor depending on a flag
    function run(address account, uint256 amountRaw, bool make) public payable {
        require(amountRaw <= type(uint128).max, "amount too large for UFixed18 packing");
        // amount is interpreted as whole units and converted via UFixed18.from(uint256)
        UFixed18 amount = UFixed18Lib.from(amountRaw);

        // read before-state: pre position for account
        (uint256 beforeOracleVersion, , ) = c.pre(account).oracleVersion == 0 ? (uint256(0), UFixed18Lib.ZERO, UFixed18Lib.ZERO) : (c.pre(account).oracleVersion, UFixed18Lib.ZERO, UFixed18Lib.ZERO);
        // Actually use public getter pre(account)
        PrePosition memory beforePre = c.pre(account);
        UFixed18 beforeMakerOpen = beforePre.openPosition.maker;
        UFixed18 beforeTakerOpen = beforePre.openPosition.taker;

        bool reverted;
        if (make) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read after-state
        PrePosition memory afterPre = c.pre(account);
        UFixed18 afterMakerOpen = afterPre.openPosition.maker;
        UFixed18 afterTakerOpen = afterPre.openPosition.taker;

        // If the call did not revert, then exactly the intended side (maker or taker) must have its pre.openPosition increased by 'amount' (or at least not decreased).
        // Because some other invariants could also change other fields, we assert the monotonic increase on the intended side and unchanged on the other side.
        if (!reverted) {
            if (make) {
                // maker increased by amount; taker not decreased
                assert(afterMakerOpen.gte(beforeMakerOpen.add(amount)) && afterTakerOpen.gte(beforeTakerOpen));
            } else {
                // taker increased by amount; maker not decreased
                assert(afterTakerOpen.gte(beforeTakerOpen.add(amount)) && afterMakerOpen.gte(beforeMakerOpen));
            }
        } else {
            // If reverted, nothing about state change is guaranteed by the contract; still assert true to have single assert reachable in both cases
            assert(reverted == true);
        }
    }

    receive() external payable {}
 }

