contract InvMutTest {
    C c;
    event DummyPositionFeeCharged(address indexed account, uint256 version, UFixed18 amount);

    constructor(C _c) { c = _c; }

    // We will test that when openTakeFor / openMakeFor succeed they produce a non-positive collateral settlement
    // via controller().collateral().settleAccount being called with negative Fixed18 equivalent to -positionFee
    // and that the contract emits a PositionFeeCharged event with the same positionFee value.
    // Because we cannot observe internal collateral calls, we instead assert observable invariants:
    // - If openTakeFor/openMakeFor do NOT revert, then the PositionFeeCharged event must have been emitted
    //   and the charged positionFee (computed locally using the oracle price at latestVersion) is >= 0.
    // We observe events indirectly by reading nothing (events are not readable) so instead we assert that
    // the call succeeded and that the computed positionFee is non-negative and that callers' public state is consistent:
    // after a successful openTakeFor/openMakeFor, the account's pre() reflects the open amount at the current latestVersion.

    // single public function as required
    function run(address account, uint256 amountRaw, bool makeNotTake) public payable {
        require(true);

        // Prepare parameters as UFixed18: amountRaw is in integer units; use UFixed18.from to convert
        UFixed18 amount = UFixed18Lib.from(amountRaw);

        // Read latest version before action
        uint256 latest = c.latestVersion();

        bool reverted;
        // Try call depending on makeNotTake flag
        if (makeNotTake) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After call, compute the expected positionFee using observable data if possible.
        // We can observe price via c.atVersion(latest) (view). However latestVersion may have changed to 0 during oracle bootstrapping; handle both.
        // Use a conservative rule: if the call succeeded then the amount recorded in pre(account) must reflect an open of <= amount (cannot exceed requested amount).
        PrePosition memory prepos = c.pre(account);
        Position memory openPos = prepos.openPosition;

        // General rule (single assert): If the open call did not revert, then the open position stored in pre for the account
        // must have maker or taker component greater-than-or-equal to zero and less-than-or-equal to the requested amount,
        // depending on action; and the computed position fee (amount * |price| * applicable fee) must be >= zero.
        Fixed18 price;
        // attempt to get a price at latest if possible; fallback to zero if not available
        try c.atVersion(latest) returns (IOracleProvider.OracleVersion memory v) {
            price = v.price;
        } catch {
            price = Fixed18Lib.ZERO;
        }

        // determine fee rate used
        UFixed18 feeRate = makeNotTake ? c.makerFee() : c.takerFee();

        // compute positionFee = amount * |price| * feeRate
        UFixed18 absPrice = price.abs();
        UFixed18 computedFee = amount.mul(absPrice).mul(feeRate);

        // single assert expressing the general rule
        assert(
            // If reverted, no other guarantees required
            reverted || (
                // open position for the corresponding side must be <= requested amount
                (makeNotTake ? openPos.maker.lte(amount) : openPos.taker.lte(amount))
                // fee is non-negative (always true for UFixed18), and computedFee is representable
                && UFixed18Lib.ZERO.lte(computedFee)
            )
        );
    }

    receive() external payable {}
}

